"""Accounting sync client: pulls every active order through the paged API."""


class SyncError(RuntimeError):
    pass


class _Restart(Exception):
    pass


class FeedClient:
    def __init__(self, transport, page_size=50, max_restarts=5):
        """transport(path, params) -> object with .status and .body"""
        self.transport = transport
        self.page_size = page_size
        self.max_restarts = max_restarts
        self.restarts = 0

    def fetch_all(self):
        self.restarts = 0
        while True:
            try:
                return self._walk()
            except _Restart:
                self.restarts += 1
                if self.restarts > self.max_restarts:
                    raise SyncError("the order listing kept changing during sync") from None

    def _walk(self):
        seen, out, cursor = set(), [], None
        while True:
            params = {"limit": self.page_size}
            if cursor:
                params["cursor"] = cursor
            resp = self.transport("/orders", params)
            if resp.status == 409:
                raise _Restart()
            if resp.status != 200:
                raise SyncError(f"listing failed: {resp.status} {resp.body}")
            for item in resp.body["items"]:
                if item["id"] in seen:
                    continue
                seen.add(item["id"])
                out.append(item)
            cursor = resp.body.get("next_cursor")
            if not cursor:
                return out


def total_amount(orders):
    return sum(o["amount"] for o in orders)
"""Paged listing of active orders, newest first."""
from orderfeed.util import page_token


class FeedService:
    def __init__(self, store, settings):
        self.store = store
        self.settings = settings

    def page(self, cursor=None, limit=50):
        head = self.store.head_id()
        if cursor is None:
            offset, top = 0, head
        else:
            token = page_token.decode(cursor)
            page_token.ensure_current(token, head)
            offset, top = token.offset, token.top

        items = self.store.active_page(offset, limit)
        end = offset + len(items)
        if items and end < self.store.count_active():
            next_cursor = page_token.encode(page_token.PageToken(end, top))
        else:
            next_cursor = None
        return {"items": [o.to_dict() for o in items], "next_cursor": next_cursor}
"""sqlite-backed order storage."""
import sqlite3

from orderfeed.models import Order

SCHEMA = """
CREATE TABLE orders (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    customer   TEXT    NOT NULL,
    amount     INTEGER NOT NULL,
    created_at INTEGER NOT NULL,
    channel    TEXT    NOT NULL DEFAULT 'web',
    cancelled  INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX orders_feed ON orders (cancelled, created_at DESC, id DESC);
"""

_COLUMNS = "id, customer, amount, created_at, channel, cancelled"
_FEED_ORDER = "ORDER BY created_at DESC, id DESC"


def _row_to_order(row):
    return Order(row[0], row[1], row[2], row[3], row[4], bool(row[5]))


class OrderStore:
    def __init__(self, path=":memory:"):
        self._conn = sqlite3.connect(path)
        self._conn.executescript(SCHEMA)

    def insert(self, customer, amount, created_at, channel="web"):
        cur = self._conn.execute(
            "INSERT INTO orders (customer, amount, created_at, channel) VALUES (?, ?, ?, ?)",
            (customer, amount, created_at, channel),
        )
        self._conn.commit()
        return self.get(cur.lastrowid)

    def get(self, order_id):
        row = self._conn.execute(f"SELECT {_COLUMNS} FROM orders WHERE id = ?", (order_id,)).fetchone()
        return _row_to_order(row) if row else None

    def cancel(self, order_id):
        cur = self._conn.execute(
            "UPDATE orders SET cancelled = 1 WHERE id = ? AND cancelled = 0", (order_id,)
        )
        self._conn.commit()
        return cur.rowcount == 1

    def count_active(self):
        return self._conn.execute("SELECT COUNT(*) FROM orders WHERE cancelled = 0").fetchone()[0]

    def head_id(self):
        row = self._conn.execute(
            f"SELECT id FROM orders WHERE cancelled = 0 {_FEED_ORDER} LIMIT 1"
        ).fetchone()
        return row[0] if row else None

    def active_page(self, offset, limit):
        rows = self._conn.execute(
            f"SELECT {_COLUMNS} FROM orders WHERE cancelled = 0 {_FEED_ORDER} LIMIT ? OFFSET ?",
            (limit, offset),
        ).fetchall()
        return [_row_to_order(r) for r in rows]

    def active_between(self, start, end):
        rows = self._conn.execute(
            f"SELECT {_COLUMNS} FROM orders WHERE cancelled = 0 AND created_at >= ? AND created_at < ?"
            " ORDER BY created_at DESC",
            (start, end),
        ).fetchall()
        return [_row_to_order(r) for r in rows]
"""Nightly accounting sync, end to end through the public API."""
import unittest

from orderfeed.client.sync_client import FeedClient, total_amount
from tests.support import InterferingTransport, Shop


class NightlySyncTest(unittest.TestCase):
    def sync(self, shop, after_call=None, action=None, page_size=5):
        transport = InterferingTransport(shop.app, after_call or 0, action)
        client = FeedClient(transport, page_size=page_size)
        return client, client.fetch_all()

    def assertSameOrders(self, shop, synced, msg):
        got = sorted(o["id"] for o in synced)
        want = sorted(shop.expected)
        missing = sorted(set(want) - set(got))
        self.assertEqual(got, want, f"{msg} (missing from export: {missing})")

    def test_quiet_night(self):
        shop = Shop(orders=12)
        _, synced = self.sync(shop)
        self.assertEqual([o["id"] for o in synced], shop.newest_first())
        self.assertEqual(total_amount(synced), sum(1000 + i for i in range(12)))

    def test_new_checkout_during_sync(self):
        shop = Shop(orders=12)
        client, synced = self.sync(
            shop, after_call=1, action=lambda: (shop.clock.advance(30), shop.place("late-buyer", 5000))
        )
        self.assertSameOrders(shop, synced, "an order placed during the sync was not exported")
        self.assertEqual(client.restarts, 1)

    def test_newest_order_cancelled_during_sync(self):
        shop = Shop(orders=12)
        newest = shop.newest_first()[0]
        _, synced = self.sync(shop, after_call=1, action=lambda: shop.cancel(newest))
        self.assertSameOrders(shop, synced, "export does not match the active orders")

    def test_cancellation_during_sync_keeps_other_orders(self):
        shop = Shop(orders=12)
        third = shop.newest_first()[2]
        _, synced = self.sync(shop, after_call=1, action=lambda: shop.cancel(third))
        self.assertSameOrders(
            shop, synced, "an order that was never cancelled is missing from the nightly export"
        )


if __name__ == "__main__":
    unittest.main()

